func factChoice163(ex *planner.Exec, target uint32) bool {
	table := &ex.FactTables[0][4]
	var solution uint32
	for row, rows := 0, table.RowCount(); row < rows; row++ {
		args := table.Row(row)
		if v := ex.V[101]; v.IsBound() && !atom.Equal(args[0], v) {
			continue
		}
		if !(atom.Equal(args[1], sv36)) {
			continue
		}
		if v := ex.V[102]; v.IsBound() && !atom.Equal(args[2], v) {
			continue
		}
		if v := ex.V[103]; v.IsBound() && !atom.Equal(args[3], v) {
			continue
		}
		if solution != target {
			solution++
			continue
		}
		if !ex.V[101].IsBound() && args[0].IsBound() {
			ex.V[101] = args[0]
		}
		if !ex.V[102].IsBound() && args[2].IsBound() {
			ex.V[102] = args[2]
		}
		if !ex.V[103].IsBound() && args[3].IsBound() {
			ex.V[103] = args[3]
		}
		return true
	}
	return false
}

